import Foundation

nonisolated enum ArtistName {
    private static let topicSuffix = " - Topic"

    /// Auto-generated artist channels are named "Artist - Topic"; show just the artist.
    static func clean(_ channelTitle: String) -> String {
        guard channelTitle.hasSuffix(topicSuffix) else { return channelTitle }
        return String(channelTitle.dropLast(topicSuffix.count))
    }

    /// YouTube's auto-generated artist channels, which carry the album versions of songs.
    static func isTopicChannel(_ channelTitle: String) -> Bool {
        channelTitle.hasSuffix(topicSuffix)
    }
}

/// The credits YouTube writes into its auto-generated music videos:
/// "Provided to YouTube by Label", then "Song · Artist · Other Artist", then the album. Their
/// "Topic" channels are sometimes named after a distributor, such as "Release - Topic", so this
/// is the only reliable artist.
nonisolated struct AutoGeneratedCredits: Equatable, Sendable {
    let artists: [String]
    let album: String?

    private static let header = "Provided to YouTube by"
    private static let separator = " · "
    private static let rightsPrefixes = ["℗", "©", "Released on:"]

    init?(description: String) {
        let lines = description
            .split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
        guard lines.count > 1, lines[0].hasPrefix(Self.header) else { return nil }
        let names = lines[1].components(separatedBy: Self.separator).dropFirst()
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
        guard !names.isEmpty else { return nil }
        artists = Array(names)
        let albumLine = lines.count > 2 ? lines[2] : nil
        album = albumLine.flatMap { line in
            Self.rightsPrefixes.contains(where: line.hasPrefix) ? nil : line
        }
    }

    /// "A", "A & B" or "A, B & C", as Apple Music writes them.
    var artist: String {
        guard let last = artists.last, artists.count > 1 else { return artists.joined() }
        return artists.dropLast().joined(separator: ", ") + " & " + last
    }
}

nonisolated enum SongTitle {
    private static let versionSeparator = " - "

    /// Drops "(Official Video)", "[Lyrics]", "(feat. X)" and similar.
    static func removingBracketedText(from text: String) -> String {
        text.replacing(#/\s*[\(\[【][^\)\]】]*[\)\]】]/#, with: "")
    }

    /// A catalog title without the version details videos often leave out:
    /// "Song (feat. X)" and "Song - 2011 Remaster" → "Song".
    static func core(of title: String) -> String {
        var core = removingBracketedText(from: title)
        if let separator = core.range(of: versionSeparator) {
            core = String(core[..<separator.lowerBound])
        }
        core = core.trimmingCharacters(in: .whitespaces)
        return core.isEmpty ? title : core
    }
}

/// What a video's title says about its recording. Music videos often add intros, skits and
/// outros, so synced lyrics timed against the album audio drift on them.
nonisolated enum VideoTitle {
    /// "Song (Official Music Video)" or "Song [MV]", but not "Song (Official Lyric Video)".
    static func isMusicVideo(_ title: String) -> Bool {
        title.contains(#/(?i)\b(?:official\s+(?:4k\s+|hd\s+|music\s+)?video|music\s+video|m/?v)\b/#)
            && !isAudio(title)
            && !title.contains(#/(?i)\b(?:lyrics?|visuali[sz]er)\b/#)
    }

    /// "Song (Official Audio)".
    static func isAudio(_ title: String) -> Bool {
        title.contains(#/(?i)\baudio\b/#)
    }

    /// A search such as "song music video", whose results should keep YouTube's order.
    static func asksForVideo(_ query: String) -> Bool {
        query.contains(#/(?i)\b(?:video|m/?v)\b/#)
    }
}

nonisolated enum ISO8601Duration {
    private static let secondsPerMinute: TimeInterval = 60
    private static let secondsPerHour: TimeInterval = 3_600
    private static let secondsPerDay: TimeInterval = 86_400
    private static let secondsPerWeek: TimeInterval = 604_800

    /// Parses YouTube durations such as "PT4M13S". Returns nil for live streams ("P0D").
    static func seconds(from value: String) -> TimeInterval? {
        guard value.hasPrefix("P") else { return nil }
        var total: TimeInterval = 0
        var digits = ""
        var isTimeSection = false
        for character in value.dropFirst() {
            if character == "T" {
                isTimeSection = true
                continue
            }
            if character.isNumber || character == "." {
                digits.append(character)
                continue
            }
            guard let amount = TimeInterval(digits) else { return nil }
            digits = ""
            switch (character, isTimeSection) {
            case ("W", false): total += amount * secondsPerWeek
            case ("D", false): total += amount * secondsPerDay
            case ("H", true): total += amount * secondsPerHour
            case ("M", true): total += amount * secondsPerMinute
            case ("S", true): total += amount
            default: return nil
            }
        }
        return total > 0 ? total : nil
    }
}

nonisolated enum TimeFormatting {
    private static let secondsPerHour: TimeInterval = 3_600

    static func string(from seconds: TimeInterval) -> String {
        let clamped = max(0, seconds)
        let duration = Duration.seconds(clamped)
        return clamped >= secondsPerHour
            ? duration.formatted(.time(pattern: .hourMinuteSecond))
            : duration.formatted(.time(pattern: .minuteSecond))
    }
}

nonisolated enum HTMLEntity {
    private static let maxEntityLength = 10
    private static let hexRadix = 16
    private static let named: [String: Character] = [
        "amp": "&", "quot": "\"", "apos": "'", "lt": "<", "gt": ">", "nbsp": " ",
    ]

    static func decode(_ entity: Substring) -> Character? {
        if let character = named[String(entity)] { return character }
        guard entity.first == "#" else { return nil }
        let number = entity.dropFirst()
        let scalarValue = number.first == "x" || number.first == "X"
            ? UInt32(number.dropFirst(), radix: hexRadix)
            : UInt32(number)
        return scalarValue.flatMap(Unicode.Scalar.init).map(Character.init)
    }

    static func isPlausibleLength(_ length: Int) -> Bool {
        length <= maxEntityLength
    }
}

nonisolated extension String {
    /// Case- and accent-insensitive containment, for names that differ between services.
    func looselyContains(_ other: String) -> Bool {
        !other.isEmpty && range(of: other, options: [.caseInsensitive, .diacriticInsensitive]) != nil
    }

    /// Either name contains the other, for "Artist" vs "Artist & Friend".
    func looselyMatches(_ other: String) -> Bool {
        looselyContains(other) || other.looselyContains(self)
    }

    /// The search endpoint returns HTML-escaped titles (e.g. `Don&#39;t Stop`).
    var decodingHTMLEntities: String {
        guard contains("&") else { return self }
        var result = ""
        var index = startIndex
        while index < endIndex {
            if self[index] == "&",
               let semicolon = self[index...].firstIndex(of: ";"),
               HTMLEntity.isPlausibleLength(distance(from: index, to: semicolon)),
               let decoded = HTMLEntity.decode(self[self.index(after: index)..<semicolon]) {
                result.append(decoded)
                index = self.index(after: semicolon)
            } else {
                result.append(self[index])
                index = self.index(after: index)
            }
        }
        return result
    }
}
